-- Source: FED_SENATE_LDA_FILINGS
-- Generated by scripts/gen_mart_models.py

-- 2026-08-26: added dedup. The loader (scripts/senate_lda_load.py) has been
-- running for hours across a rate-limited API with heavy 429 retries; a retry
-- after a partially-successful page write re-appends already-landed rows --
-- same failure class already found and fixed in the OSHA loader this week.
-- filing_uuid duplicated up to 6x on 10,485 rows before this fix. Dedup here
-- treats the raw landing table as append-only and keeps the newest row per
-- filing_uuid; the loader's own duplicate-row bug is a separate, still-open
-- fix (out of scope for this dbt-layer patch).

with source as (
    select * from {{ source('ripple_raw', 'FED_SENATE_LDA_FILINGS') }}
),

deduped as (
    select *,
        row_number() over (
            partition by FILING_UUID
            order by _INGESTED_AT desc
        ) as _row_num
    from source
    where FILING_UUID is not null
)

select
    FILING_UUID as filing_uuid,
    FILING_TYPE as filing_type,
    FILING_TYPE_DISPLAY as filing_type_display,
    FILING_YEAR as filing_year,
    FILING_PERIOD as filing_period,
    FILING_PERIOD_DISPLAY as filing_period_display,
    DT_POSTED as dt_posted,
    INCOME as income,
    EXPENSES as expenses,
    REGISTRANT_ID as registrant_id,
    REGISTRANT_NAME as registrant_name,
    REGISTRANT_DESCRIPTION as registrant_description,
    REGISTRANT_CITY as registrant_city,
    REGISTRANT_STATE as registrant_state,
    REGISTRANT_COUNTRY as registrant_country,
    CLIENT_ID as client_id,
    CLIENT_NAME as client_name,
    CLIENT_DESCRIPTION as client_description,
    CLIENT_STATE as client_state,
    CLIENT_COUNTRY as client_country,
    LOBBYING_ISSUES as lobbying_issues,
    GOVERNMENT_ENTITIES as government_entities,
    LOBBYIST_NAMES as lobbyist_names,
    SPECIFIC_ISSUES as specific_issues,
    try_to_date(TERMINATION_DATE) as termination_date,
    FOREIGN_ENTITY_LISTED as foreign_entity_listed
from deduped
where _row_num = 1
